head.script:
scwin.gLdMktTp = js_market;

// session 값을 control 에 binding 시키는 함수.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        panel_kos.hide();
        scwin.hideDebugCtrls();
        scwin.initPage();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26504.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listDisclosureReceiveStatistic();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26504.btn_Search_onclick" });
    }
};

