 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26504.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Excel_Today_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_Today_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF26504.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_TODAY, {fileName: "공시접수통계", sheetName: 'c:\\abs\\test.xls', type: 16});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26504.btn_Excel_Today_onclick" });
    }
};

/**
 * @method
 * @name chk_TODAY_onclick
 * @description chk_TODAY 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_TODAY_onclick = function() {
    try {
        if (chk_TODAY.getValue() === "Y") {
            $c.cm.setColumnProp(grd_PERIOD, 'SEND_D', 'Show', 'true');
            dts_PERIOD.removeAll();
            dts_TODAY.removeAll();
            chk_PERIOD.setValue("N");
            panel_period.hide();
            panel_today.show("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26504.chk_TODAY_onclick" });
    }
};

/**
 * @method
 * @name chk_PERIOD_onclick
 * @description chk_PERIOD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_PERIOD_onclick = function() {
    try {
        if (chk_PERIOD.getValue() === "Y") {
            $c.cm.setColumnProp(grd_PERIOD, 'SEND_D', 'Show', 'false');
            dts_PERIOD.removeAll();
            dts_TODAY.removeAll();
            chk_TODAY.setValue("N");
            panel_period.show("");
            panel_today.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26504.chk_PERIOD_onclick" });
    }
};

