///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listDisclosureReceiveStatistic
 * @description list Disclosure Receive Statistic 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listDisclosureReceiveStatistic = async function() {
    let MKT_ID = rdo_MKT_ID.getValue();
    if (MKT_ID === "") {
        await $c.win.alert("[시장구분]을 선택하세요.");
        return;
    }
    let MKT_ID = rdo_MKT_ID.getValue();
    const SDATE = edt_SDATE.getValue();
    const EDATE = edt_EDATE.getValue();
    const TODAY = edt_TODAY.getValue();
    const bTODAY = chk_TODAY.getValue();
    const bPERIOD = chk_PERIOD.getValue();
    if (bTODAY === "N" && bPERIOD === "N") {
        await $c.win.alert("[금일] 또는 [기간별]을 선택하세요.");
        return;
    }
    let FLAG = "TODAY";
    FLAG = (bTODAY === "Y") ? "TODAY" : "PERIOD";
    if (FLAG === "TODAY") {
        if (TODAY === "") {
            await $c.win.alert("[금일-일자]를 입력하세요.");
            edt_TODAY.focus();
            return;
        }
    } else {
        if (SDATE === "") {
            await $c.win.alert("[기간별-시작일]을 입력하세요.");
            edt_SDATE.focus();
            return;
        }
        if (EDATE === "") {
            await $c.win.alert("[기간별-종료일]을 입력하세요.");
            edt_EDATE.focus();
            return;
        }
    }
    url += "&MKT_ID=" + MKT_ID;
    url += "&TODAY=" + TODAY;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&FLAG=" + FLAG;
    url += "&SCREN_ID=" + 'ULDSTF26504.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_TODAY",
        action : "/DisclosureCountStatistics.do",
        ref : "",
        target : "dts_TODAY=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&MKT_ID=" + MKT_ID;
    url += "&TODAY=" + TODAY;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&FLAG=" + FLAG;
    const sbmOptions2 = {
        id : "sbm_dts_PERIOD",
        action : "/DisclosureCountStatistics.do",
        ref : "",
        target : "dts_PERIOD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    if (js_market === "9") {
        rdo_MKT_ID.setDisabled(false);
    } else {
        rdo_MKT_ID.setDisabled(true);
        if (js_market !== '1') {
            // 유가가 아닐때만 보여줌
            panel_kos.show("");
        }
    }
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    chk_TODAY.setValue("Y");
    edt_TODAY.setValue($c.ut.cGetToday2());
    panel_today.show("");
    // alert(gLdMktTp);
    chk_PERIOD.setValue("N");
    panel_period.hide();
    cmb_PeriodTp.setValue("5");
};

/**
 * @method
 * @name statusCnt
 * @description status Cnt 처리
 * @returns {void}
 * @hidden N
 */
scwin.statusCnt = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF26505", "/dsclsrch/ULDSTF26505.gfm", "공시건수조회", 20, 20, 1270, 780, "");
};

/**
 * @method
 * @name oldStatus
 * @description old Status 처리
 * @returns {void}
 * @hidden N
 */
scwin.oldStatus = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF26501", "/dsclsrch/ULDSTF26501.gfm", "구 공시접수통계", 20, 20, 1080, 620 + 40, "");
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_mkt.hide();
};
